/**
 * Expo config plugin: Android release packaging.
 *
 * Only lossless packaging settings live here. Native libraries are stored compressed in the APK
 * (`useLegacyPackaging`), which makes the download smaller without changing any code.
 *
 * R8 code shrinking and resource shrinking are deliberately OFF (user decision, 2026-10-11): they can
 * strip classes that libraries reach only through JNI or reflection, and that breaks only at runtime
 * on a device. Revisit them for a Play Store build, with a device test pass.
 *
 * android/ is generated by `expo prebuild`, so these settings must live here, not in android/.
 */
const { withGradleProperties } = require('expo/config-plugins');

const GRADLE_PROPERTIES = {
  'expo.useLegacyPackaging': 'true',
};

module.exports = function withAndroidReleaseSize(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(GRADLE_PROPERTIES)) {
      const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === key);
      if (existing) existing.value = value;
      else cfg.modResults.push({ type: 'property', key, value });
    }
    return cfg;
  });
};
